class ExtensionHelper{constructor(){this.installed=!1,this.version=null,this._messageId=0,this._pendingRequests=new Map,this._init()}_init(){window.addEventListener("message",event=>{if(event.source!==window)return;const message=event.data;if(!(!message||message.source!=="github-drive-extension")){if(message.type==="EXTENSION_LOADED"){this.installed=!0,this.version=message.version,console.log("[Extension] \u6269\u5C55\u5DF2\u5B89\u88C5\uFF0C\u7248\u672C:",this.version);return}if(message.type&&message.type.endsWith("_RESPONSE")){const requestId=message.requestId,resolve=this._pendingRequests.get(requestId);resolve&&(this._pendingRequests.delete(requestId),resolve(message))}}}),window.__GITHUB_DRIVE_EXTENSION__?(this.installed=!0,this.version=window.__GITHUB_DRIVE_EXTENSION_VERSION__,console.log("[Extension] \u68C0\u6D4B\u5230\u6269\u5C55\u5DF2\u5B89\u88C5\uFF0C\u7248\u672C:",this.version)):setTimeout(()=>{window.__GITHUB_DRIVE_EXTENSION__?(this.installed=!0,this.version=window.__GITHUB_DRIVE_EXTENSION_VERSION__,console.log("[Extension] \u5EF6\u8FDF\u68C0\u6D4B\u5230\u6269\u5C55\u5DF2\u5B89\u88C5")):console.log("[Extension] \u672A\u68C0\u6D4B\u5230\u6269\u5C55\uFF0C\u5C06\u4F7F\u7528\u7EAF\u524D\u7AEF\u6A21\u5F0F")},1e3)}_sendMessage(type,data={}){return new Promise((resolve,reject)=>{if(!this.installed){reject(new Error("\u6269\u5C55\u672A\u5B89\u88C5"));return}const requestId=++this._messageId;this._pendingRequests.set(requestId,resolve),window.postMessage({source:"github-drive-page",type,requestId,...data},"*"),setTimeout(()=>{this._pendingRequests.has(requestId)&&(this._pendingRequests.delete(requestId),reject(new Error("\u6269\u5C55\u54CD\u5E94\u8D85\u65F6")))},3e4)})}isAvailable(){return this.installed}getVersion(){return this.version}async getToken(){try{return(await this._sendMessage("GET_TOKEN")).token||null}catch(e){return console.warn("[Extension] \u83B7\u53D6 Token \u5931\u8D25:",e.message),null}}async setToken(token){try{return(await this._sendMessage("SET_TOKEN",{token})).ok}catch(e){return console.warn("[Extension] \u4FDD\u5B58 Token \u5931\u8D25:",e.message),!1}}async clearToken(){try{return(await this._sendMessage("CLEAR_TOKEN")).ok}catch(e){return console.warn("[Extension] \u6E05\u9664 Token \u5931\u8D25:",e.message),!1}}async getUser(){try{return(await this._sendMessage("GET_USER")).user||null}catch(e){return console.warn("[Extension] \u83B7\u53D6\u7528\u6237\u4FE1\u606F\u5931\u8D25:",e.message),null}}async apiRequest(method,path,body=null,headers={},useToken=!0){try{return await this._sendMessage("API_REQUEST",{method,path,body,headers,useToken})}catch(e){throw console.warn("[Extension] API \u8BF7\u6C42\u5931\u8D25:",e.message),e}}}const extensionHelper=new ExtensionHelper;
